-- Executes only in the separate restored synthetic CI database. Roll back probes.
begin;
select no_plan();
select ok(exists(select 1 from public.inquiries),'restored website enquiries');
select ok(exists(select 1 from public.manual_booking_contacts),'restored manual contacts');
select ok(exists(select 1 from public.website_booking_intakes i join public.booking_requests r on r.id=i.request_id join public.inquiries e on e.id=r.inquiry_id),'restored atomic enquiry/request links');
select ok(exists(select 1 from public.booking_quotes where status='ISSUED'),'restored issued quotes');
select ok(exists(select 1 from public.booking_deposit_verifications where decision='VERIFIED'),'restored verified payment events');
select ok(exists(select 1 from public.calendar_rate_revisions where status='PUBLISHED'),'restored published rates');
select ok(exists(select 1 from public.property_occupancies where kind='OWNER_BLOCK'),'restored owner blocks');
select ok(exists(select 1 from public.booking_operation_events where action='CANCEL'),'restored cancellation review history');
select ok(exists(select 1 from public.booking_operation_events where action='COMPLETE'),'restored completion history');
select ok(exists(select 1 from public.media_audit_events),'restored media audits');
select ok(exists(select 1 from public.booking_notification_outbox),'restored notification tasks');
select throws_ok($$update public.booking_quotes set amount_total=amount_total+1 where id=(select id from public.booking_quotes where status='ISSUED' limit 1)$$,'23514',null,'restored issued quotation snapshot cannot mutate');
select throws_ok($$update public.booking_deposits set amount=amount+1 where id=(select id from public.booking_deposits limit 1)$$,'23514',null,'restored original payment cannot mutate');
select throws_ok($$delete from public.booking_deposit_verifications where id=(select id from public.booking_deposit_verifications limit 1)$$,'23514',null,'restored verification history cannot delete');
select throws_ok($$update public.booking_reservations set overnight_guest_count=1 where id=(select id from public.booking_reservations limit 1)$$,'23514',null,'restored reservation snapshot cannot mutate');
select is((select count(*)::int from public.property_occupancies a join public.property_occupancies b on a.id<b.id and a.active and b.active and a.property_id=b.property_id and daterange(a.check_in_date,a.check_out_date,'[)') && daterange(b.check_in_date,b.check_out_date,'[)')),0,'no restored active overlap');
select ok(not exists(select 1 from pg_constraint where connamespace='public'::regnamespace and contype in ('f','c') and not convalidated),'restored validated foreign keys and checks');
select ok(exists(select 1 from pg_constraint where conname='no_overlapping_active_property_stays' and contype='x'),'restored property exclusion');
select ok(not has_function_privilege('anon','public.confirm_booking_reservation(uuid,uuid,uuid)','EXECUTE'),'anonymous confirmation still denied');
select ok(not has_function_privilege('authenticated','public.accept_website_booking(jsonb,text,uuid,text)','EXECUTE'),'trusted intake still server-only');
select ok(not has_table_privilege('anon','public.manual_booking_contacts','SELECT'),'anonymous contacts denied');
select ok(not has_table_privilege('anon','public.booking_deposits','SELECT'),'anonymous payments denied');
select ok(not has_table_privilege('authenticated','public.booking_operation_events','INSERT'),'direct lifecycle writes denied');
select ok(not has_table_privilege('authenticated','storage.objects','UPDATE') or exists(select 1 from pg_policies where schemaname='storage' and tablename='objects'),'storage access retains policies');
select set_config('request.jwt.claim.sub',(select id::text from auth.users where email='ui-owner@example.invalid'),true);
set local role authenticated;
select ok(public.is_ten29_owner(),'restored OWNER membership enforced');
select ok(exists(select 1 from public.booking_quotes where status='ISSUED'),'OWNER can read protected restored quotes');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from auth.users where email='ui-manager@example.invalid'),true);
set local role authenticated;
select ok(public.is_ten29_admin() and not public.is_ten29_owner(),'restored manager cannot become OWNER');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-999999999999',true);
select is((select count(*)::int from public.manual_booking_contacts),0,'nonmember restored contacts hidden by RLS');
select is((select count(*)::int from public.booking_quotes),0,'nonmember restored quotes hidden by RLS');
select * from finish();
rollback;
